<?php
namespace App\Filament\Resources\OnboardingSteps\Schemas;
use Filament\Forms\Components\DatePicker; use Filament\Forms\Components\DateTimePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Forms\Components\Textarea; use Filament\Forms\Components\Toggle; use Filament\Schemas\Schema;
class OnboardingStepForm { public static function configure(Schema $schema): Schema { return $schema->components([Select::make('event_id')->relationship('event','name')->required(), TextInput::make('title')->required(), Textarea::make('description')->required(), Select::make('trigger_key')->options(['registration_created'=>'Registration created','email_verified'=>'Email verified','deposit_paid'=>'Deposit paid','final_payment_due'=>'Final payment due','event_near'=>'Event near'])->required(), TextInput::make('delay_days')->numeric()->default(0), Select::make('mail_template_id')->relationship('mailTemplate','name'), TextInput::make('sort_order')->numeric()->default(0), Toggle::make('is_active')]); } }
